func NewErrMRSWConflict(m string) error {
	return &ErrMRSWConflict{msg: m}
}

func (r *MultiRSW) BeginRead() error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.owner != "" {
		return NewErrMRSWConflict("MSRW conflict owner: " + r.owner)
	}
	r.numReaders++
	return nil
}

func (r *MultiRSW) EndRead() {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.numReaders--
	if r.numReaders < 0 {
		panic("reader count went negative")
	}
	if r.numReaders == 0 {
		r.cond.Broadcast()
	}
}

func (r *MultiRSW) BeginWrite(owner string) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if owner == "" {
		panic("owner cannot be empty")
	}
	if r.owner != "" {
		return NewErrMRSWConflict("MSRW conflict owner: " + r.owner)
	}
	if r.numReaders > 0 {
		return NewErrMRSWConflict(fmt.Sprintf("MSRW conflict %d readers active", r.numReaders))
	}
	r.owner = owner
	return nil
}

func (r *MultiRSW) BeginWriteBlocking(owner string, done <-chan struct{}) error {
	if owner == "" {
		panic("owner cannot be empty")
	}

	// Goroutine to wake us via Broadcast if done is closed while
	// we are blocked in cond.Wait().
	stop := make(chan struct{})
	defer close(stop)
	go func() {
		select {
		case <-done:
			r.cond.Broadcast()
		case <-stop:
		}
	}()

	r.mu.Lock()
	defer r.mu.Unlock()
	for r.owner != "" || r.numReaders > 0 {
		select {
		case <-done:
			return NewErrMRSWConflict("MSRW write wait cancelled")
		default:
		}
		r.cond.Wait()
	}
	select {
	case <-done:
		return NewErrMRSWConflict("MSRW write wait cancelled")
	default:
	}
	r.owner = owner
	return nil
}

func (r *MultiRSW) EndWrite() {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.owner == "" {
		panic("write done received but no write is active")
	}
	r.owner = ""
	r.cond.Broadcast()
}

func (r *MultiRSW) UpgradeToWriter(owner string) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.owner != "" {
		return NewErrMRSWConflict("MSRW conflict owner: " + r.owner)
	}
	if r.numReaders > 1 {
		return NewErrMRSWConflict(fmt.Sprintf("MSRW conflict %d readers active", r.numReaders))
	}
	if r.numReaders == 0 {
		panic("upgrade attempted with no readers")
	}
	r.owner = owner
	r.numReaders = 0
	return nil
}

func (r *ReadyChannels) Register(ch <-chan struct{}) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.chans = append(r.chans, ch)
	go func() {
		<-ch
		r.numClosedReadyChannels.Add(1)
	}()
}

func (r *ReadyChannels) Ready() bool {
	r.mu.Lock()
	defer r.mu.Unlock()
	return int(r.numClosedReadyChannels.Load()) == len(r.chans)
}

func (r *ReadyTarget[T]) Subscribe(target T) <-chan struct{} {
	ch := make(chan struct{})
	r.mu.Lock()
	defer r.mu.Unlock()
	if target <= r.currentTarget {
		close(ch)
	} else {
		subscriber := &Subscriber[T]{
			target: target,
			ch:     ch,
		}
		r.subscribers = append(r.subscribers, subscriber)
	}
	return ch
}

func (r *ReadyTarget[T]) Unsubscribe(ch <-chan struct{}) {
	r.mu.Lock()
	defer r.mu.Unlock()
	for i, subscriber := range r.subscribers {
		if subscriber.ch == ch {
			r.subscribers = append(r.subscribers[:i], r.subscribers[i+1:]...)
			break
		}
	}
}

func (r *ReadyTarget[T]) Signal(index T) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if index <= r.currentTarget {
		return
	}
	r.currentTarget = index
	var remainingSubscribers []*Subscriber[T]
	for _, subscriber := range r.subscribers {
		if index >= subscriber.target {
			close(subscriber.ch)
		} else {
			remainingSubscribers = append(remainingSubscribers, subscriber)
		}
	}
	r.subscribers = remainingSubscribers
}

func (r *ReadyTarget[T]) Len() int {
	r.mu.RLock()
	defer r.mu.RUnlock()
	return len(r.subscribers)
}

func (r *Request[T]) Close() {
	for _, c := range r.flushChans {
		close(c)
	}
}

type BasicAuther interface {
	BasicAuth() (string, string, bool)
}

type Credential struct {
	Username string   `json:"username,omitempty"`
	Password string   `json:"password,omitempty"`
	Perms    []string `json:"perms,omitempty"`
}

type CredentialsStore struct {
	store map[string]string
	perms map[string]map[string]bool
}

func NewCredentialsStore() *CredentialsStore {
	return &CredentialsStore{
		store: make(map[string]string),
		perms: make(map[string]map[string]bool),
	}
}

func NewCredentialsStoreFromFile(path string) (*CredentialsStore, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	c := NewCredentialsStore()
	return c, c.Load(f)
}

func (c *CredentialsStore) Load(r io.Reader) error {
	dec := json.NewDecoder(r)
	// Read open bracket
	_, err := dec.Token()
	if err != nil {
		return err
	}

	var cred Credential
	for dec.More() {
		err := dec.Decode(&cred)
		if err != nil {
			return err
		}
		c.store[cred.Username] = cred.Password
		c.perms[cred.Username] = make(map[string]bool, len(cred.Perms))
		for _, p := range cred.Perms {
			c.perms[cred.Username][p] = true
		}
	}

	// Read closing bracket.
	_, err = dec.Token()
	if err != nil {
		return err
	}

	return nil
}

func (c *CredentialsStore) Check(username, password string) bool {
	pw, ok := c.store[username]
	return ok && pw == password
}

func (c *CredentialsStore) Password(username string) (string, bool) {
	pw, ok := c.store[username]
	return pw, ok
}

func (c *CredentialsStore) HasPerm(username string, perm string) bool {
	if m, ok := c.perms[username]; ok {
		if _, ok := m[perm]; ok {
			return true
		}
	}

	if m, ok := c.perms[AllUsers]; ok {
		if _, ok := m[perm]; ok {
			return true
		}
	}

	return false
}

func (c *CredentialsStore) HasAnyPerm(username string, perm ...string) bool {
	return func(p []string) bool {
		for i := range p {
			if c.HasPerm(username, p[i]) {
				return true
			}
		}
		return false
	}(perm)
}

func (c *CredentialsStore) AA(username, password, perm string) bool {
	// No credential store? Auth is not even enabled.
	if c == nil {
		return true
	}

	// Is the required perm granted to all users, including anonymous users?
	if c.HasAnyPerm(AllUsers, perm, PermAll) {
		return true
	}

	// At this point a username needs to have been supplied.
	if username == "" {
		return false
	}

	// Authenticate the user.
	if !c.Check(username, password) {
		return false
	}

	// Is the specified user authorized?
	return c.HasAnyPerm(username, perm, PermAll)
}

func (c *CredentialsStore) HasPermRequest(b BasicAuther, perm string) bool {
	username, _, ok := b.BasicAuth()
	return ok && c.HasPerm(username, perm)
}

func NewS3Client(endpoint, region, accessKey, secretKey, bucket, key string, opts *S3ClientOpts) (*S3Client, error) {
	// Load the default config
	cfg, err := config.LoadDefaultConfig(context.Background(),
		config.WithRegion(region),
	)
	if err != nil {
		return nil, fmt.Errorf("unable to load SDK config, %v", err)
	}

	// If credentials are provided, set them
	if accessKey != "" && secretKey != "" {
		cfg.Credentials = aws.NewCredentialsCache(credentials.NewStaticCredentialsProvider(accessKey, secretKey, ""))
	}

	// If an endpoint is provided, set it and the path style
	s3 := s3.NewFromConfig(cfg, func(o *s3.Options) {
		if opts != nil {
			if endpoint != "" {
				if !hasProtocol(endpoint) {
					endpoint = fmt.Sprintf("https://%s", endpoint)
				}
				o.BaseEndpoint = aws.String(endpoint)
			}
			o.UsePathStyle = opts.ForcePathStyle
		}
	})

	client := &S3Client{
		endpoint:  endpoint,
		region:    region,
		accessKey: accessKey,
		secretKey: secretKey,
		bucket:    bucket,
		key:       key,

		s3:         s3,
		uploader:   manager.NewUploader(s3),
		downloader: manager.NewDownloader(s3),
	}
	if opts != nil {
		client.timestamp = opts.Timestamp
	}
	return client, nil
}

func (s *S3Client) String() string {
	if s.endpoint == "" || isAWSEndpoint(s.endpoint) {
		// Native Amazon S3, use AWS's S3 URL format
		return fmt.Sprintf("s3://%s/%s", s.bucket, s.key)
	}
	return fmt.Sprintf("%s/%s/%s", s.endpoint, s.bucket, s.key)
}

func (s *S3Client) Upload(ctx context.Context, reader io.Reader, id string) error {
	key := s.key
	if s.timestamp {
		if s.now == nil {
			s.now = func() time.Time {
				return time.Now().UTC()
			}
		}
		key = TimestampedPath(key, s.now())
	}
	input := &s3.PutObjectInput{
		Bucket: aws.String(s.bucket),
		Key:    aws.String(key),
		Body:   reader,
	}

	if id != "" {
		input.Metadata = map[string]string{
			AWSS3IDKey: id,
		}
	}
	_, err := s.uploader.Upload(ctx, input)
	if err != nil {
		return fmt.Errorf("failed to upload to %v: %w", s, err)
	}
	return nil
}

func (s *S3Client) CurrentID(ctx context.Context) (string, error) {
	input := &s3.HeadObjectInput{
		Bucket: aws.String(s.bucket),
		Key:    aws.String(s.key),
	}

	result, err := s.s3.HeadObject(ctx, input)
	if err != nil {
		return "", fmt.Errorf("failed to get object head for %v: %w", s, err)
	}

	id, ok := result.Metadata[AWSS3IDKey]
	if !ok {
		return "", fmt.Errorf("sum metadata not found for %v", s)
	}
	return id, nil
}

func TimestampedPath(path string, t time.Time) string {
	parts := strings.Split(path, "/")
	parts[len(parts)-1] = fmt.Sprintf("%s_%s", t.Format("20060102150405"), parts[len(parts)-1])
	return strings.Join(parts, "/")
}

func isAWSEndpoint(s string) bool {
	return strings.HasSuffix(s, "amazonaws.com")
}

func hasProtocol(s string) bool {
	return strings.Contains(s, "://")
}

func ReadConfigFile(filename string) ([]byte, error) {
	f, err := os.Open(filename)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	data, err := io.ReadAll(f)
	if err != nil {
		return nil, err
	}

	data = []byte(os.ExpandEnv(string(data)))
	return data, nil
}

